import React from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useNotifications } from '../contexts/NotificationContext';

const NavigationBar = () => {
  const { user, isAuthenticated, isAdmin, isTeacher, isStudent, logout } = useAuth();
  const { unreadCount } = useNotifications();
  const navigate = useNavigate();
  const location = useLocation();

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  const isActive = (path) => location.pathname === path;

  return (
    <header
      style={{
        backgroundColor: '#ffffff',
        borderBottom: '1px solid var(--border)',
        position: 'sticky',
        top: 0,
        zIndex: 50,
        boxShadow: '0 1px 2px 0 rgba(0, 0, 0, 0.05)',
      }}
    >
      <div
        style={{
          maxWidth: '1280px',
          margin: '0 auto',
          padding: '0.85rem 1.5rem',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
        }}
      >
        {/* Brand */}
        <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', textDecoration: 'none' }}>
          <div
            style={{
              width: '38px',
              height: '38px',
              borderRadius: 'var(--radius-md)',
              background: 'linear-gradient(135deg, var(--primary), var(--accent))',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: 'white',
              fontWeight: 800,
              fontSize: '1.2rem',
            }}
          >
            📋
          </div>
          <div>
            <span style={{ fontSize: '1.15rem', fontWeight: 800, color: 'var(--text-main)', letterSpacing: '-0.02em', display: 'block' }}>
              NoticeHub
            </span>
            <span style={{ fontSize: '0.7rem', color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              School Notice System
            </span>
          </div>
        </Link>

        {/* Nav links */}
        <nav style={{ display: 'flex', alignItems: 'center', gap: '1rem', flexWrap: 'wrap' }}>
          <Link
            to="/"
            style={{
              fontWeight: 600,
              fontSize: '0.9rem',
              color: isActive('/') ? 'var(--primary)' : 'var(--text-main)',
              padding: '0.4rem 0.6rem',
            }}
          >
            Public Board
          </Link>

          <Link
            to="/about"
            style={{
              fontWeight: 600,
              fontSize: '0.9rem',
              color: isActive('/about') ? 'var(--primary)' : 'var(--text-main)',
              padding: '0.4rem 0.6rem',
            }}
          >
            About
          </Link>

          {isAuthenticated ? (
            <>
              {isStudent && (
                <Link
                  to="/student/dashboard"
                  style={{
                    fontWeight: 600,
                    fontSize: '0.9rem',
                    color: isActive('/student/dashboard') ? 'var(--primary)' : 'var(--text-main)',
                    padding: '0.4rem 0.6rem',
                  }}
                >
                  Dashboard
                </Link>
              )}

              {isTeacher && (
                <>
                  <Link
                    to="/teacher/dashboard"
                    style={{
                      fontWeight: 600,
                      fontSize: '0.9rem',
                      color: isActive('/teacher/dashboard') ? 'var(--primary)' : 'var(--text-main)',
                      padding: '0.4rem 0.6rem',
                    }}
                  >
                    Dashboard
                  </Link>
                  <Link
                    to="/teacher/create-notice"
                    style={{
                      fontWeight: 600,
                      fontSize: '0.9rem',
                      color: isActive('/teacher/create-notice') ? 'var(--primary)' : 'var(--text-main)',
                      padding: '0.4rem 0.6rem',
                    }}
                  >
                    + Add Notice
                  </Link>
                  <Link
                    to="/teacher/analytics"
                    style={{
                      fontWeight: 600,
                      fontSize: '0.9rem',
                      color: isActive('/teacher/analytics') ? 'var(--primary)' : 'var(--text-main)',
                      padding: '0.4rem 0.6rem',
                    }}
                  >
                    Analytics
                  </Link>
                </>
              )}

              {isAdmin && (
                <>
                  <Link
                    to="/admin/dashboard"
                    style={{
                      fontWeight: 600,
                      fontSize: '0.9rem',
                      color: isActive('/admin/dashboard') ? 'var(--primary)' : 'var(--text-main)',
                      padding: '0.4rem 0.6rem',
                    }}
                  >
                    Admin Hub
                  </Link>
                  <Link
                    to="/admin/users"
                    style={{
                      fontWeight: 600,
                      fontSize: '0.9rem',
                      color: isActive('/admin/users') ? 'var(--primary)' : 'var(--text-main)',
                      padding: '0.4rem 0.6rem',
                    }}
                  >
                    Users
                  </Link>
                  <Link
                    to="/admin/audit-logs"
                    style={{
                      fontWeight: 600,
                      fontSize: '0.9rem',
                      color: isActive('/admin/audit-logs') ? 'var(--primary)' : 'var(--text-main)',
                      padding: '0.4rem 0.6rem',
                    }}
                  >
                    Audit
                  </Link>
                  <Link
                    to="/teacher/analytics"
                    style={{
                      fontWeight: 600,
                      fontSize: '0.9rem',
                      color: isActive('/teacher/analytics') ? 'var(--primary)' : 'var(--text-main)',
                      padding: '0.4rem 0.6rem',
                    }}
                  >
                    Analytics
                  </Link>
                </>
              )}

              {/* Notification icon */}
              <Link
                to="/notifications"
                className="btn btn-secondary btn-sm"
                style={{ position: 'relative' }}
              >
                🔔
                {unreadCount > 0 && (
                  <span
                    style={{
                      position: 'absolute',
                      top: '-6px',
                      right: '-6px',
                      backgroundColor: 'var(--danger)',
                      color: 'white',
                      fontSize: '0.7rem',
                      fontWeight: 700,
                      borderRadius: '50%',
                      width: '18px',
                      height: '18px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                    }}
                  >
                    {unreadCount}
                  </span>
                )}
              </Link>

              {/* User badge & logout */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                <Link to="/profile" style={{ fontSize: '0.85rem', fontWeight: 600, color: 'var(--text-main)' }}>
                  👤 {user?.fullName || user?.username} ({user?.role})
                </Link>
                <button type="button" onClick={handleLogout} className="btn btn-secondary btn-sm">
                  Logout
                </button>
              </div>
            </>
          ) : (
            <Link to="/login" className="btn btn-primary btn-sm">
              Sign In
            </Link>
          )}
        </nav>
      </div>
    </header>
  );
};

export default NavigationBar;
